arguments.oldText:
function attachDrag(grid){
  var items=grid.querySelectorAll(".disc-item");
  Array.prototype.forEach.call(items,function(item){
    item.addEventListener("dragstart",function(e){
      dragState={item:item,list:item.closest(".disc-list")};
      item.classList.add("is-drag");
      e.dataTransfer.effectAllowed="move";
      try{e.dataTransfer.setData("text/plain","x")}catch(err){}
      updateRanksFromDOM();
    });
    item.addEventListener("dragend",function(){
      item.classList.remove("is-drag");
      dragState=null;
      updateRanksFromDOM();
      updateButtons();
    });
    item.addEventListener("dragover",function(e){
      e.preventDefault();
      if(!dragState)return;
      var pos=dragState.item.closest(".disc-list");
      var idx=items.indexOf(dragState.item);
      var itemsArr=Array.prototype.slice.call(dragState.list.querySelectorAll(".disc-item"));
      var targetIdx=idx<itemsArr.length-1?itemsArr[idx+1]:null;
      if(targetIdx)targetIdx.classList.add("is-drop");
    });
    item.addEventListener("drop",function(e){
      e.preventDefault();
      var itemsArr=Array.prototype.slice.call(dragState.list.querySelectorAll(".disc-item"));
      var target=itemsArr[items.indexOf(e.target.closest(".disc-item"))+1];
      if(dragState.item){
        if(target){dragState.list.insertBefore(dragState.item,target);}
        else{dragState.list.appendChild(dragState.item);}
      }
      updateRanksFromDOM();
      updateButtons();
    });
    item.addEventListener("dragover",function(e){
      if(e.target!==dragState.item&&dragState.item){e.target.classList.remove("is-drop");}
    });
  });
}

arguments.newText:
function attachDrag(grid){
  var lists=grid.querySelectorAll(".disc-list");
  Array.prototype.forEach.call(lists,function(list){
    list.addEventListener("dragover",function(e){
      if(!dragState)return;
      e.preventDefault();
      e.stopPropagation();
      list.classList.add("is-drop");
      var y=e.clientY;
      var items=Array.prototype.slice.call(list.querySelectorAll(".disc-item"));
      var pos=-1;
      for(var i=0;i<items.length;i++){
        var r=items[i].getBoundingClientRect();
        if(y<r.top+r.height/2){pos=i;break;}
      }
      if(pos===items.length)pos=items.length-1;
      var target=items[pos]||list;
      // remove highlight
      Array.prototype.forEach.call(list.querySelectorAll(".disc-item.is-drop"),function(el){el.classList.remove("is-drop")});
      if(target)target.classList.add("is-drop");
      dragState.insertBefore=items[pos]; // placeholder
    });
    list.addEventListener("drop",function(e){
      e.preventDefault();
      list.classList.remove("is-drop");
      Array.prototype.forEach.call(list.querySelectorAll(".disc-item.is-drop"),function(el){el.classList.remove("is-drop")});
      if(!dragState)return;
      var list2=dragState.list;
      var drag=dragState.item;
      var items=Array.prototype.slice.call(list2.querySelectorAll(".disc-item"));
      var idx=items.indexOf(drag);
      // recompute insertion point using last hover position
      if(dragState.pos!=null){
        var itemsArr=Array.prototype.slice.call(list2.querySelectorAll(".disc-item"));
        if(dragState.pos===itemsArr.length){
          list2.appendChild(drag);
        }else{
          list2.insertBefore(drag,itemsArr[dragState.pos]);
        }
      }
      dragState=null;
      updateRanksFromDOM();
      updateButtons();
    });
  });
  // fallback: if dropped outside a list, still commit
  document.addEventListener("dragend",function(){
    Array.prototype.forEach.call(document.querySelectorAll(".disc-item.is-drop"),function(el){el.classList.remove("is-drop")});
    dragState=null;
  });
}

