function attachDrag(grid){
  var lists=grid.querySelectorAll(".disc-list");
  Array.prototype.forEach.call(lists,function(list){
    list.addEventListener("dragover",function(e){
      if(!dragState)return;
      e.preventDefault();
      e.stopPropagation();
      var y=e.clientY;
      var items=Array.prototype.slice.call(list.querySelectorAll(".disc-item"));
      var pos=-1;
      for(var i=0;i<items.length;i++){
        var r=items[i].getBoundingClientRect();
        if(y<r.top+r.height/2){pos=i;break;}
      }
      dragState.pos=pos===-1?items.length:pos;
      // highlight
      Array.prototype.forEach.call(list.querySelectorAll(".disc-item"),function(el){el.classList.remove("is-drop")});
      if(dragState.pos!==-1&&dragState.pos<items.length){
        items[dragState.pos].classList.add("is-drop");
      }else{
        list.classList.add("is-drop");
      }
    });
    list.addEventListener("drop",function(e){
      e.preventDefault();
      list.classList.remove("is-drop");
      Array.prototype.forEach.call(list.querySelectorAll(".disc-item.is-drop"),function(el){el.classList.remove("is-drop")});
      if(!dragState)return;
      var list2=dragState.list;
      var drag=dragState.item;
      var items=Array.prototype.slice.call(list2.querySelectorAll(".disc-item"));
      var idx=items.indexOf(drag);
      // recompute insertion point using last hover position
      if(dragState.pos!=null){
        var itemsArr=Array.prototype.slice.call(list2.querySelectorAll(".disc-item"));
        if(dragState.pos===itemsArr.length){
          list2.appendChild(drag);
        }else{
          list2.insertBefore(drag,itemsArr[dragState.pos]);
        }
      }
      dragState=null;
      updateRanksFromDOM();
      updateButtons();
    });
  });
  // fallback: if dropped outside a list, still commit
  document.addEventListener("dragend",function(){
    Array.prototype.forEach.call(document.querySelectorAll(".disc-item.is-drop"),function(el){el.classList.remove("is-drop")});
    dragState=null;
  });
}

