const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto('file:///tmp/disc-pi-ki2q4tle/run/index.html');

  // 1. App renders
  const appVisible = await page.locator('.app').isVisible();
  console.log('app visible:', appVisible);

  const title = await page.textContent('.app__title');
  console.log('title:', title);

  // 2. Items present in step 0
  const itemCount = await page.locator('.disc-item').count();
  console.log('items step0:', itemCount); // expect 12 (3 cards x 4)

  // 3. Drag item 1 of first list to position before item 2
  //    First list is the first .disc-list. Items 0..3
  const firstList = page.locator('.app .disc-list').nth(0);
  const items = firstList.locator('.disc-item');
  // Drag item at index 1 down to after item 3 (position 3 -> insert before last)
  // Simple: drag item index 0 to after index 2
  await items.nth(0).dragTo(items.nth(2));
  const order = await firstList.locator('.disc-item .q').allTextContents();
  console.log('order after drag:', order.join(' | '));

  // 4. Click through all steps
  for (let i = 0; i < 7; i++) {
    const btn = page.locator('.app .app__actions button:nth-child(2)');
    const disabled = await btn.isDisabled();
    console.log('step', i, 'next disabled:', disabled);
    await btn.click();
    const itemCountNow = await page.locator('.disc-item').count();
    console.log('  items now:', itemCountNow);
  }

  // 5. Finish
  await page.locator('.app .app__actions button:nth-child(2)').click();
  await page.waitForSelector('#result', { state: 'visible' });
  const resultTitle = await page.textContent('.result__title');
  const total = await page.textContent('.result__total');
  console.log('result title:', resultTitle);
  console.log('result total:', total);
  const chips = await page.locator('.chip').count();
  console.log('chips:', chips);

  // 6. reset
  await page.click('.result__actions .btn--ghost');
  const appVisible2 = await page.locator('.app').isVisible();
  console.log('app visible after reset:', appVisible2);

  await browser.close();
  console.log('DONE OK');
})().catch(e => { console.error(e); process.exit(1); });

