};

/* ---------- состояние ---------- */
var score={d:0,i:0,s:0,c:0};
var step=0;
var dragState=null; /* {item, list, pos} */

function escapeHTML(s){return s.replace(/[&<>"']/g,function(m){
  return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m];
})}
function buildStepHTML(idx){
  var cards=STEPS[idx];
  var html='';
  for(var g=0;g<cards.length;g++){
    html+='<div class="card"><div class="card__title"><span>Я наиболее</span></div><ul class="disc-list">';
    for(var r=0;r<cards[g].length;r++){
      var c=cards[g][r];
      html+='<li class="disc-item" draggable="true" data-type="'+c.t+'" data-q="'+escapeHTML(c.q)+'">';
      html+='<span class="q">'+c.q+'</span><span class="rank">'+(r+1)+'</span></li>';
    }
    html+='</ul><div class="card__foot">Я наименее</div></div>';
  }
  return html;
}
function canLeave(idx){
  var cards=STEPS[idx];
  for(var c=0;c<cards.length;c++){
    for(var j=0;j<cards[c].length;j++){
      if(cards[c][j].rank==null)return false;
    }
  }
  return true;
}
function recomputeScore(){
  score={d:0,i:0,s:0,c:0};
  for(var k=0;k<STEPS.length;k++){
    var cards=STEPS[k];
    for(var c=0;c<cards.length;c++){
      var card=cards[c];
      for(var j=0;j<card.length;j++){
        var rank=card[j].rank;
        if(rank!=null){
          var pts=5-rank;
          score[card[j].t]+=pts;
        }
      }
    }
  }
}
function updateButtons(){
  var next=document.querySelector("#app .app__actions button:nth-child(2)");
  if(next)next.disabled=!canLeave(step);
}
function updateRanksFromDOM(){
  var lists=document.querySelectorAll(".disc-list");
  for(var li=0;li<lists.length;li++){
    var list=lists[li];
    var items=Array.prototype.slice.call(list.querySelectorAll(".disc-item"));
    for(var i=0;i<items.length;i++){
      items[i].querySelector(".rank").textContent=(i+1);
    }
    for(var j=0;j<items.length;j++){
      STEPS[step][li][j].rank=j+1;
    }
  }
  recomputeScore();
}

function renderApp(){
  var container=document.getElementById("app");
  container.innerHTML="";
  var app=document.createElement("div");app.className="app";
  var close=document.createElement("button");
  close.className="app__close";close.setAttribute("aria-label","Скрыть");
  close.innerHTML='<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none"><path d="M6 6l12 12M18 6L6 18" stroke="#e7eef5" stroke-width="2.2" stroke-linecap="round"/></svg>';
  close.onclick=function(){app.style.display="none";showHint();};
  var head=document.createElement("div");head.className="app__head";
  head.innerHTML='<h1 class="app__title">Тестирование DISC</h1><p class="app__sub">Помните — чем честнее вы с тестом, тем точнее результаты!</p><div class="app__lead">Разместите блоки в порядке от наиболее похожего на вас до наименее похожего</div>';
  var tabs=document.createElement("div");tabs.className="tabs";
  for(var k=0;k<STEPS.length;k++){
    var tb=document.createElement("button");tb.className="tab"+(k===step?" is-active":"");
    tb.textContent=STEP_NAMES[k];
    tb.disabled=k>step;
    tb.onclick=(function(ix){return function(){if(ix<=step)go(ix);};})(k);
    tabs.appendChild(tb);
  }
  var body=document.createElement("div");body.className="app__body";
  var grid=document.createElement("div");grid.className="grid3";
  grid.innerHTML=buildStepHTML(step);
  body.appendChild(grid);
  var prog=document.createElement("div");prog.className="progress";
  var pbar=document.createElement("div");pbar.className="progress__bar";
  pbar.style.width=((step+1)/STEPS.length*100)+"%";
  prog.appendChild(pbar);body.appendChild(prog);
  app.appendChild(close);app.appendChild(head);app.appendChild(tabs);app.appendChild(body);
  var actions=document.createElement("div");actions.className="app__actions";
  var prev=document.createElement("button");prev.className="btn btn--ghost";prev.textContent="Назад";
  prev.disabled=step===0;prev.onclick=function(){if(step>0)go(step-1);};
  var next=document.createElement("button");next.className="btn btn--primary";
  next.textContent=step===STEPS.length-1?"Завершить тест":"Далее";
  actions.appendChild(prev);actions.appendChild(next);
  next.onclick=function(){if(step===STEPS.length-1)finish();else go(step+1);};
  app.appendChild(actions);
  container.appendChild(app);
  attachDrag(grid);
  updateRanksFromDOM();
}

function attachDrag(grid){
  var items=grid.querySelectorAll(".disc-item");
  Array.prototype.forEach.call(items,function(item){
    item.addEventListener("dragstart",function(e){
      dragState={item:item,list:item.closest(".disc-list"),pos:-1};
      item.classList.add("is-drag");
      e.dataTransfer.effectAllowed="move";
      try{e.dataTransfer.setData("text/plain","x")}catch(err){}
    });
  });
  var lists=grid.querySelectorAll(".disc-list");
  Array.prototype.forEach.call(lists,function(list){
    list.addEventListener("dragover",function(e){
      if(!dragState)return;
      e.preventDefault();
      var y=e.clientY;
      var lis=Array.prototype.slice.call(list.querySelectorAll(".disc-item"));
      var pos=-1;
      for(var i=0;i<lis.length;i++){
        var r=lis[i].getBoundingClientRect();
        if(y<r.top+r.height/2){pos=i;break;}
      }
      dragState.pos=(pos===-1)?lis.length:pos;
      Array.prototype.forEach.call(lis,function(el){el.classList.remove("is-drop")});
      if(dragState.pos>=0&&dragState.pos<lis.length){
        lis[dragState.pos].classList.add("is-drop");
      }else{
        list.classList.add("is-drop");
      }
    });
    list.addEventListener("drop",function(e){
      e.preventDefault();
      var dropState=dragState;
      if(!dropState)return;
      var list2=dropState.list;
      var drag=dropState.item;
      Array.prototype.forEach.call(list2.querySelectorAll(".disc-item.is-drop"),function(el){el.classList.remove("is-drop")});
      list.classList.remove("is-drop");
      var itemsArr=Array.prototype.slice.call(list2.querySelectorAll(".disc-item"));
      var p=dropState.pos;
      if(p===itemsArr.length){
        list2.appendChild(drag);
      }else if(p>=0){
        list2.insertBefore(drag,itemsArr[p]);
      }
      dragState=null;
      updateRanksFromDOM();
      updateButtons();
    });
  });
  document.addEventListener("dragend",function(){
    Array.prototype.forEach.call(document.querySelectorAll(".disc-item.is-drag,.disc-item.is-drop,.disc-list.is-drop"),function(el){
      el.classList.remove("is-drag","is-drop");
    });
    dragState=null;
  });
}

function go(to){
  step=to;renderApp();
}
function showHint(){}
function finish(){
  recomputeScore();
  var total=score.d+score.i+score.s+score.c;
  var maxType=null,mx=-1;
  for(var t in score){if(score[t]>mx){mx=score[t];maxType=t;}}
  if(maxType===null){maxType="d";}
  var info=TYPE_INFO[maxType];
  var r=document.getElementById("result");
  var html='';
  html+='<div class="result__kicker">Ваш профиль DISC</div>';
  html+='<div class="result__title">'+info.name+'</div>';
  var maxTotal=STEPS.length*3*10;
  html+='<div class="result__total">Общий балл: <strong>'+total+'</strong> из '+maxTotal+' · Доминирующая черта: '+info.name+'</div>';
  html+='<div class="result__profile">';
  var order=["d","i","s","c"];
  for(var oi=0;oi<order.length;oi++){
    var p=Math.min(100,Math.round(score[order[oi]]/4*100));
    html+='<div class="chip" style="border-color:'+cssColor(order[oi])+'"><div class="chip__letter" style="color:'+cssColor(order[oi])+'">'+order[oi].toUpperCase()+'</div>';
    html+='<div class="chip__name">'+TYPE_INFO[order[oi]].name+'</div>';
    html+='<div class="chip__val">'+score[order[oi]]+' баллов</div>';
    html+='<div class="chip__bar"><div class="chip__fill" style="width:'+p+'%;background:'+cssColor(order[oi])+'"></div></div>';
    html+='</div>';
  }
  html+='</div>';
  html+='<div class="result__type"><strong>'+info.name+' — ваша доминирующая черта</strong>'+info.desc+'</div>';
  html+='<div class="result__actions"><button class="btn btn--primary" onclick="location.reload()">Пройти заново</button>';
  html+='<button class="btn btn--ghost" onclick="resetTest()">Вернуться к тесту</button></div>';
  r.innerHTML=html;
  r.hidden=false;
  document.getElementById("app").style.display="none";
  window.scrollTo(0,0);
}
function resetTest(){
  for(var k=0;k<STEPS.length;k++){
    STEPS[k].forEach(function(card){card.forEach(function(it){it.rank=null;});});
  }
  score={d:0,i:0,s:0,c:0};
  step=0;
  var r=document.getElementById("result");r.hidden=true;
  renderApp();
}
function cssColor(t){
  if(t==="d")return"#f59e0b";if(t==="i")return"#38bdf8";if(t==="s")return"#34d399";return"#c084fc";
}

/* ---------- инициализация ---------- */
renderApp();
</script>
</body>
</html>
